import { useEffect, useRef, useState } from "react";
import { t } from "../i18n";
import type { Lang, Stage } from "../types";

interface Props {
  lang: Lang;
  stage: Stage;
  setStage: (s: Stage) => void;
  text: string;
  setText: (s: string) => void;
  files: File[];
  setFiles: (f: File[]) => void;
  audios: File[];
  setAudios: (f: File[]) => void;
  loading: boolean;
  error: string | null;
  onSubmit: () => void;
  followUp?: boolean;
}

const MAX_IMAGES = 6;
const MAX_AUDIO = 3;
const MAX_RECORD_SECONDS = 120;

// Synthetic samples generated by scripts/make_demo_data.py and scripts/make_test_data.py
const SAMPLES = [
  { file: "scam-chat.png", kind: "image", ne: "COD → advance + QR", en: "COD → advance + QR" },
  { file: "honest-chat.png", kind: "image", ne: "इमानदार बिक्रेता", en: "Honest seller" },
  { file: "refund-fee-chat.png", kind: "image", ne: "रिफन्ड शुल्क", en: "Refund fee" },
  { file: "seller-reply.png", kind: "reply", ne: "↩ बिक्रेताको जवाफ", en: "↩ Seller's reply" },
  { file: "voice-victim.ogg", kind: "audio", ne: "🎙 पैसा तिरें, सामान आएन", en: "🎙 Paid, nothing arrived" },
] as const;

function useObjectUrl(file: File): string | undefined {
  const [url, setUrl] = useState<string>();
  useEffect(() => {
    const u = URL.createObjectURL(file);
    setUrl(u);
    return () => URL.revokeObjectURL(u);
  }, [file]);
  return url;
}

export function Thumb({ file }: { file: File }) {
  const url = useObjectUrl(file);
  return url ? <img src={url} alt={file.name} /> : null;
}

export function AudioPlayer({ file }: { file: File }) {
  const url = useObjectUrl(file);
  return url ? <audio controls preload="metadata" src={url} /> : null;
}

export default function InputView(p: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const [recording, setRecording] = useState(false);
  const [recordSeconds, setRecordSeconds] = useState(0);
  const [micError, setMicError] = useState<string | null>(null);

  function addFiles(list: FileList | null) {
    if (!list) return;
    const all = Array.from(list);
    const images = all.filter((f) => f.type.startsWith("image/"));
    const audio = all.filter((f) => f.type.startsWith("audio/") || f.type === "video/mp4");
    if (images.length) p.setFiles([...p.files, ...images].slice(0, MAX_IMAGES));
    if (audio.length) p.setAudios([...p.audios, ...audio].slice(0, MAX_AUDIO));
  }

  async function loadSample(file: string, kind: "image" | "audio" | "reply") {
    const blob = await (await fetch(`/demo/${file}`)).blob();
    const f = new File([blob], file, { type: blob.type || (kind === "audio" ? "audio/ogg" : "image/png") });
    if (kind === "reply") {
      // Follow-up sample: add the seller's reply next to the evidence already loaded.
      p.setFiles([...p.files.filter((x) => x.name !== file), f].slice(0, MAX_IMAGES));
      return;
    }
    p.setText("");
    if (kind === "image") {
      p.setFiles([f]);
      p.setAudios([]);
    } else {
      p.setAudios([f]);
      p.setFiles([]);
      p.setStage("after_payment");
    }
  }

  async function toggleRecording() {
    if (recording) {
      recorderRef.current?.stop();
      return;
    }
    setMicError(null);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const recorder = new MediaRecorder(stream);
      const chunks: Blob[] = [];
      recorder.ondataavailable = (e) => e.data.size && chunks.push(e.data);
      recorder.onstop = () => {
        stream.getTracks().forEach((track) => track.stop());
        setRecording(false);
        const type = recorder.mimeType || "audio/webm";
        const ext = type.includes("mp4") ? "m4a" : type.includes("ogg") ? "ogg" : "webm";
        const file = new File([new Blob(chunks, { type })], `voice-${Date.now()}.${ext}`, { type });
        p.setAudios([...p.audios, file].slice(0, MAX_AUDIO));
      };
      recorderRef.current = recorder;
      recorder.start();
      setRecording(true);
    } catch {
      setMicError(t("micDenied", p.lang));
    }
  }

  useEffect(() => {
    if (!recording) return;
    setRecordSeconds(0);
    const id = setInterval(
      () =>
        setRecordSeconds((s) => {
          if (s + 1 >= MAX_RECORD_SECONDS) recorderRef.current?.stop();
          return s + 1;
        }),
      1000,
    );
    return () => clearInterval(id);
  }, [recording]);

  const canSubmit =
    !p.loading && !recording && (p.text.trim() !== "" || p.files.length > 0 || p.audios.length > 0);
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (!p.loading) return;
    setElapsed(0);
    const id = setInterval(() => setElapsed((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, [p.loading]);

  const canRecord = typeof MediaRecorder !== "undefined" && !!navigator.mediaDevices?.getUserMedia;

  return (
    <section className="stack">
      {p.followUp && <p className="notice">{t("replyHint", p.lang)}</p>}
      <div className="hero">
        <h1>{t("tagline", p.lang)}</h1>
        <p className="muted">{t("intro", p.lang)}</p>
      </div>

      <fieldset className="card">
        <legend>{t("stageQuestion", p.lang)}</legend>
        <div className="segmented">
          <button aria-pressed={p.stage === "before_payment"} onClick={() => p.setStage("before_payment")}>
            {t("stageBefore", p.lang)}
          </button>
          <button aria-pressed={p.stage === "after_payment"} onClick={() => p.setStage("after_payment")}>
            {t("stageAfter", p.lang)}
          </button>
        </div>
      </fieldset>

      <div className="card stack-sm">
        <button className="dropzone" onClick={() => inputRef.current?.click()}>
          <span className="dropzone-icon" aria-hidden>＋</span>
          {t("addScreenshots", p.lang)}
          <span className="muted small">PNG / JPG / WebP · {t("voiceFormats", p.lang)}</span>
        </button>
        <input
          ref={inputRef}
          type="file"
          accept="image/png,image/jpeg,image/webp,audio/*,.m4a,.ogg,.opus,.mp3,.wav,.aac"
          multiple
          hidden
          onChange={(e) => {
            addFiles(e.target.files);
            e.target.value = "";
          }}
        />
        {p.files.length > 0 && (
          <ul className="thumbs">
            {p.files.map((f, i) => (
              <li key={i}>
                <Thumb file={f} />
                <button
                  className="thumb-remove"
                  aria-label={`Remove ${f.name}`}
                  onClick={() => p.setFiles(p.files.filter((_, j) => j !== i))}
                >
                  ×
                </button>
              </li>
            ))}
          </ul>
        )}

        {canRecord && (
          <button
            className={recording ? "record recording" : "record"}
            onClick={toggleRecording}
            disabled={!recording && p.audios.length >= MAX_AUDIO}
          >
            <span className="record-dot" aria-hidden />
            {recording ? `${t("stopRecording", p.lang)} · ${recordSeconds}s` : t("recordVoice", p.lang)}
          </button>
        )}
        {micError && <p className="error small">{micError}</p>}
        {p.audios.length > 0 && (
          <ul className="audio-list">
            {p.audios.map((f, i) => (
              <li key={i}>
                <span className="small">🎙 {f.name}</span>
                <AudioPlayer file={f} />
                <button
                  className="ghost small"
                  aria-label={`Remove ${f.name}`}
                  onClick={() => p.setAudios(p.audios.filter((_, j) => j !== i))}
                >
                  ×
                </button>
              </li>
            ))}
          </ul>
        )}

        <div className="samples">
          <span className="label">{t("trySample", p.lang)}</span>
          {SAMPLES.filter((s) => (s.kind === "reply") === !!p.followUp).map((s) => (
            <button key={s.file} className="chip" onClick={() => loadSample(s.file, s.kind)}>
              {s[p.lang]}
            </button>
          ))}
        </div>

        <label className="stack-xs">
          <span className="label">{t("pasteLabel", p.lang)}</span>
          <textarea
            rows={5}
            value={p.text}
            onChange={(e) => p.setText(e.target.value)}
            placeholder={t("pastePlaceholder", p.lang)}
          />
        </label>
      </div>

      {p.error && <p className="error" role="alert">{p.error}</p>}

      <button className="primary big" disabled={!canSubmit} onClick={p.onSubmit}>
        {p.loading ? `${t("checking", p.lang)} ${elapsed}s` : t("check", p.lang)}
      </button>
      {p.loading && <p className="muted small" aria-live="polite">{t("checkingHint", p.lang)}</p>}
      <p className="muted small">{t("privacy", p.lang)}</p>
    </section>
  );
}
